def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    vals = {}
    for row in grid:
        for x in row:
            vals[x] = vals.get(x, 0) + 1
    bg = max(vals, key=vals.get)
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not marks:
        return out
    marker = grid[marks[0][0]][marks[0][1]]
    fill = 2
    active_rows = [r for r in range(h) if any(grid[r][c] == marker for c in range(w))]
    rtop, rbot = min(active_rows), max(active_rows)
    active_cols = [c for c in range(w) if any(grid[r][c] == marker for r in range(h))]
    cmin, cmax = min(active_cols), max(active_cols)
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 4:
            for c in range(min(cols), max(cols)+1):
                if grid[r][c] == bg:
                    out[r][c] = fill
    # The uppermost marker row completes the full horizontal span.
    topcols = [c for c in range(w) if grid[rtop][c] == marker]
    if len(topcols) >= 2:
        for c in range(cmin, cmax+1):
            if grid[rtop][c] == bg:
                out[rtop][c] = fill
    row_counts = [sum(grid[r][c] == marker for c in range(w)) for r in range(h)]
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 3 and (c in (cmin, cmax) or any(row_counts[r] <= 2 for r in rows)):
            for r in range(rtop, rbot+1):
                if grid[r][c] == bg:
                    out[r][c] = fill
    return out
